#include <string>

class Solution {
public:
    std::string maxBitwiseXor(std::string s, std::string t) {
        int ones = 0;
        for (char c : t) if (c == '1') ones++;
        int zeros = t.length() - ones;
        std::string res = "";
        for (char c : s) {
            if (c == '0') {
                if (ones > 0) { res.push_back('1'); ones--; }
                else { res.push_back('0'); zeros--; }
            } else {
                if (zeros > 0) { res.push_back('1'); zeros--; }
                else { res.push_back('0'); ones--; }
            }
        }
        return res;
    }
};

class Solution {
    public String maxBitwiseXor(String s, String t) {
        int ones = 0;
        for (char c : t.toCharArray()) if (c == '1') ones++;
        int zeros = t.length() - ones;
        StringBuilder sb = new StringBuilder();
        for (char c : s.toCharArray()) {
            if (c == '0') {
                if (ones > 0) { sb.append('1'); ones--; }
                else { sb.append('0'); zeros--; }
            } else {
                if (zeros > 0) { sb.append('1'); zeros--; }
                else { sb.append('0'); ones--; }
            }
        }
        return sb.toString();
    }
}

function maxBitwiseXor(s, t) {
    let ones = 0;
    for (const c of t) if (c === '1') ones++;
    let zeros = t.length - ones;
    const res = [];
    for (const c of s) {
        if (c === '0') {
            if (ones > 0) { res.push('1'); ones--; }
            else { res.push('0'); zeros--; }
        } else {
            if (zeros > 0) { res.push('1'); zeros--; }
            else { res.push('0'); ones--; }
        }
    }
    return res.join('');
}
